import clusterdata.datatypes.JobEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.zip.GZIPInputStream;

public class JobEventSource implements SourceFunction<JobEvent> {

    private static final long serialVersionUID = 1L;

    private final String path;
    private volatile boolean running = true;

    public JobEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<JobEvent> ctx) throws Exception {
        try (GZIPInputStream gz = new GZIPInputStream(Files.newInputStream(Paths.get(path)));
             BufferedReader br = new BufferedReader(new InputStreamReader(gz, StandardCharsets.UTF_8))) {
            String line;
            while (running && (line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                JobEvent e = JobEvent.fromCsv(line);
                // emit with event-time timestamp in milliseconds (dataset is in microseconds)
                ctx.collectWithTimestamp(e, e.timestamp / 1000L);
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
