import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.util.Collector;

public class LongestSessionPerJob extends AppBase {

    // Google trace FINISH event type for both task and job events.
    private static final int EVENT_TYPE_SUBMIT = 0;
    private static final int EVENT_TYPE_FINISH = 4;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        System.out.println("output  " + outputPath);
        // Session (stage) inactivity gap in seconds. Default is 10 minutes (600s).
        final int sessSize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .returns(TypeInformation.of(TaskEvent.class))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.timestamp / 1000L))
                .filter(new FilterFunction<TaskEvent>() {
                    @Override
                    public boolean filter(TaskEvent e) {
                        return e.eventType == EVENT_TYPE_SUBMIT;
                    }
                });

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .returns(TypeInformation.of(JobEvent.class))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.timestamp / 1000L))
                .filter(new FilterFunction<JobEvent>() {
                    @Override
                    public boolean filter(JobEvent e) {
                        return e.eventType == EVENT_TYPE_FINISH;
                    }
                });

        // Stage gap expressed in microseconds, matching the raw timestamp unit used in state.
        final long gapMicros = sessSize * 1_000_000L;

        DataStream<Tuple2<Long, Long>> results = tasks
                .keyBy((KeySelector<TaskEvent, Long>) e -> e.jobId)
                .connect(jobs.keyBy((KeySelector<JobEvent, Long>) e -> e.jobId))
                .process(new LongestStageFunction(gapMicros))
                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {}));

        DataStream<String> lines = results.map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .returns(TypeInformation.of(String.class));

        if (out != null) {
            lines.addSink(sinkOrTest(null));
        } else {
            lines.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

    /**
     * Keyed co-process function that identifies activity stages per jobId.
     *
     * Semantic contract (enforced here):
     *  - A stage is formed only by task SUBMIT events (contributing-event predicate).
     *  - A new stage begins when the gap between consecutive SUBMITs exceeds `gapMicros`.
     *  - Output is produced only when a job FINISH event is observed AND the key has
     *    accumulated at least one SUBMIT (output-eligibility predicate).
     *  - FINISH alone never produces a row for a key with no qualifying activity.
     *  - Emission is deferred via an event-time timer scheduled at the FINISH timestamp
     *    so all task events earlier than FINISH are guaranteed to be processed first.
     */
    public static class LongestStageFunction
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Long>> {

        private static final long serialVersionUID = 1L;

        private final long gapMicros;

        private transient ValueState<Long> currentStageCount;
        private transient ValueState<Long> longestStageCount;
        private transient ValueState<Long> lastSubmitTs;      // microseconds
        private transient ValueState<Boolean> hasActivity;    // output-eligibility flag
        private transient ValueState<Boolean> emitted;        // guard against double-emit

        public LongestStageFunction(long gapMicros) {
            this.gapMicros = gapMicros;
        }

        @Override
        public void open(Configuration conf) {
            currentStageCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("currentStageCount", Long.class));
            longestStageCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("longestStageCount", Long.class));
            lastSubmitTs = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("lastSubmitTs", Long.class));
            hasActivity = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("hasActivity", Boolean.class));
            emitted = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent task, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            long ts = task.timestamp; // microseconds
            Long last = lastSubmitTs.value();
            Long cur = currentStageCount.value();
            Long longest = longestStageCount.value();
            if (cur == null) cur = 0L;
            if (longest == null) longest = 0L;

            if (last != null && (ts - last) > gapMicros) {
                // Close prior stage.
                if (cur > longest) longest = cur;
                cur = 0L;
            }
            cur++;
            if (cur > longest) longest = cur;

            currentStageCount.update(cur);
            longestStageCount.update(longest);
            lastSubmitTs.update(ts);
            hasActivity.update(true);
        }

        @Override
        public void processElement2(JobEvent job, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            // Defer emission until watermark reaches the FINISH timestamp so that any
            // task SUBMITs with earlier event time are guaranteed to be processed first.
            long finishMs = job.timestamp / 1000L;
            ctx.timerService().registerEventTimeTimer(finishMs);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean already = emitted.value();
            if (Boolean.TRUE.equals(already)) {
                return;
            }

            // Output-eligibility gate: emit only when qualifying activity exists.
            if (!Boolean.TRUE.equals(hasActivity.value())) {
                return;
            }

            Long longest = longestStageCount.value();
            if (longest == null) {
                return;
            }

            out.collect(Tuple2.of(ctx.getCurrentKey(), longest));
            emitted.update(true);

            // Clear state to free memory.
            currentStageCount.clear();
            longestStageCount.clear();
            lastSubmitTs.clear();
            hasActivity.clear();
        }
    }
}
